import{_ as a,o as t,c as o,a4 as n}from"./chunks/framework.C83Ss68L.js";const g=JSON.parse('{"title":"Why KatanaKit","description":"The goals behind the toolkit, its design stance, and when it is the wrong tool for the job.","frontmatter":{"title":"Why KatanaKit","description":"The goals behind the toolkit, its design stance, and when it is the wrong tool for the job."},"headers":[],"relativePath":"explanation/why-katanakit.md","filePath":"explanation/why-katanakit.md","lastUpdated":1791568280000}'),i={name:"explanation/why-katanakit.md"};function s(r,e,l,h,d,c){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="why-katanakit" tabindex="-1">Why KatanaKit <a class="header-anchor" href="#why-katanakit" aria-label="Permalink to &quot;Why KatanaKit&quot;">​</a></h1><p>Most TypeScript projects rewrite the same plumbing: a fetch wrapper, an error envelope, storage with the same four methods, date helpers, a logger. KatanaKit is that plumbing, written once and kept framework-agnostic — not a framework, and not an app template.</p><h2 id="what-it-is" tabindex="-1">What it is <a class="header-anchor" href="#what-it-is" aria-label="Permalink to &quot;What it is&quot;">​</a></h2><p>A <strong>service toolkit</strong>: small services with one consistent shape, each usable alone. The main barrel exports <code>use*</code> functions for HTTP, logging, storage, dates, formatting, filesystem, workers and more; framework adapters layer on top as thin bindings. You adopt it piece by piece — <code>useLogger</code> today, the query cache next week — and nothing forces the rest.</p><h2 id="the-goals-this-design-serves" tabindex="-1">The goals this design serves <a class="header-anchor" href="#the-goals-this-design-serves" aria-label="Permalink to &quot;The goals this design serves&quot;">​</a></h2><ol><li><strong>One consistent API.</strong> Every public helper is a <code>use*</code> function over a Singleton facade, every fallible call returns the same Safe Result, every configuration entry point is a <code>define*Config</code>. Learn one service and you can guess the shape of the next. The reasoning is recorded in <a href="/katanakit-js/explanation/decisions/adr-0002-singleton-facades">ADR-0002</a> and <a href="/katanakit-js/explanation/decisions/adr-0001-safe-results">ADR-0001</a>.</li><li><strong>A pure core, thin edges.</strong> Domain logic never touches <code>window</code> or the filesystem; runtime I/O lives one layer out with SSR guards, and framework integrations live on subpaths so they never enter a bundle that does not use them (<a href="/katanakit-js/explanation/decisions/adr-0004-hexagonal-core">ADR-0004</a>, <a href="/katanakit-js/explanation/decisions/adr-0003-adapter-subpath-exports">ADR-0003</a>).</li><li><strong>Failures are values, not surprises.</strong> The network is unreliable and payloads lie; <code>{ data, error, ok }</code> plus Zod validation at the boundary make both facts visible in the types. See the <a href="/katanakit-js/tutorials/first-api-client">Tutorial</a> for what that feels like in use.</li><li><strong>Install only what you use.</strong> Runtime dependencies are counted — one (<code>@js-temporal/polyfill</code>). Framework packages, faker, photoswipe and the database client are optional peers, loaded only when imported.</li><li><strong>Docs that cannot drift.</strong> The API reference is generated from the source on every docs build, so a signature cannot silently disagree with its documentation (<a href="/katanakit-js/explanation/decisions/adr-0005-docs-as-code">ADR-0005</a>).</li></ol><h2 id="when-katanakit-is-the-wrong-tool" tabindex="-1">When KatanaKit is the wrong tool <a class="header-anchor" href="#when-katanakit-is-the-wrong-tool" aria-label="Permalink to &quot;When KatanaKit is the wrong tool&quot;">​</a></h2><ul><li><strong>You want a framework to own the app.</strong> Next.js, Nuxt and Astro already solve data fetching, routing and server functions natively. Use their solutions in the parts of the app they own; mixing two data layers costs more than it saves. KatanaKit is at its best in the gaps they leave — helpers, nodes, services, side projects.</li><li><strong>You need zero conventions.</strong> The <code>use*</code> naming, Safe Results and process-wide registries are opinions. If a codebase cannot absorb them, a smaller utility library per problem will fit better.</li><li><strong>One dependency already solves your problem.</strong> If all you need is date math, <code>date-fns</code> is the honest answer. The optional-peer design exists so the toolkit never forces a choice — and so you can leave.</li></ul><h2 id="what-it-is-not" tabindex="-1">What it is not <a class="header-anchor" href="#what-it-is-not" aria-label="Permalink to &quot;What it is not&quot;">​</a></h2><p>Not a UI kit (that is the <a href="/katanakit-js/ui-kit/">UI Kit</a> section), not a database layer (Prisma is an optional integration), and not an application framework. It is glue for the parts every project rewrites — designed so the day a part stops earning its place, you can delete it without a migration.</p>',10)])])}const u=a(i,[["render",s]]);export{g as __pageData,u as default};
